function weekStart(){const d=new Date();d.setUTCHours(0,0,0,0);d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return +d}
function emptyProject(){return {id:null,title:'Upload your first recording',created:Date.now(),revision:0,bpm:120,ppq:480,tuning:[40,45,50,55,59,64],capo:0,duration:0,parts:{guitar:[]},originalParts:{guitar:[]},empty:true}}
