for(const p of data.projects.filter(p=>Date.now()-p.created>=30*86400000))audioRecord(p.id,'delete').catch(()=>{});data.projects=data.projects.filter(p=>Date.now()-p.created<30*86400000);if(data.week!==weekStart()){data.week=weekStart();data.used=0}
for(const p of data.projects){if(p.parts.lead){p.parts={guitar:p.parts.lead};p.originalParts={guitar:p.originalParts.lead}}}
let project=data.projects[0]||emptyProject(),part='guitar',selected=null,source='synth',position=0,playing=false,ctx=null,timer=null,last=0,lastTick=-1,lastBar=-1,zoom=1,conversion=null,media=new Audio(),audioFiles=new Map();
