function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function quota(){$('#projectCount').textContent=data.projects.length;$('.quota').innerHTML='<span class="tiny">LOCAL MUSCRIPTOR SERVER</span><strong>Muscriptor</strong><p>Audio is sent to your local model server.<br>No conversion limit in this build.</p>'}
function ticksPerBar(){return (project.meter||4)*480}
