function pitchName(p){return ['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][p%12]+(Math.floor(p/12)-1)}
function render(){quota();$('#songTitle').textContent=project.title;$('#scoreTitle').textContent=project.title;$('#songDescription').textContent=project.id?project.parts.guitar.length+' notes from your audio · '+project.engine:'No sample notes. Upload a recording to start.';$('.song-status .green').textContent=project.id?'AI transcription':'No audio loaded';$('.song-status .muted').textContent=project.recording==='mix'?'Mixed audio · no source separation':'Single guitar recommended';$('#meterMeta').textContent=(project.meter||4)+'/4';$('#reviewBtn').hidden=!(project.suppressedNotes?.length);$('#reviewBtn').textContent='Review '+(project.suppressedNotes?.filter(n=>!n.restored).length||0)+' excluded notes';$('#bpmMeta').textContent='♩ '+project.bpm+' BPM';$('#durationMeta').textContent='◷ '+time(duration());$('#tempoLabel').textContent='♩ = '+project.bpm;$('#revisionTag').textContent='Revision '+project.revision;$('#expiry').textContent=project.id?'Available until '+new Date(project.created+30*86400000).toLocaleDateString(window.appLocale||'en-US',{month:'short',day:'numeric'}):'';$('#partLabel').textContent='Guitar · AI note estimates';$('#exportBtn').disabled=!project.id;$('#playBtn').disabled=!project.id;$('.quality p').textContent=project.id?project.warnings.join(' '):'Your TAB appears only after real model inference.';renderScore();updateTimeline();inspect()}
function renderScore(){if(!project.id){$('#tablature').innerHTML='<div class="empty-score"><span>♫</span><h3>Let’s hear your guitar.</h3><p>Real audio in. AI-estimated notes out.</p></div>';return}let html='';for(let row=0;row<Math.ceil(Math.max(1,Math.ceil(duration()*project.bpm/(60*(project.meter||4))))/4);row++){html+='<div class="staff-row"><div class="string-labels">'+['e','B','G','D','A','E'].map(s=>`<span>${s}</span>`).join('')+'</div>';for(let bar=row*4;bar<Math.min(row*4+4,Math.max(1,Math.ceil(duration()*project.bpm/(60*(project.meter||4)))));bar++){html+=`<div class="measure" data-bar="${bar}"><span class="measure-number">${bar+1}</span>`;for(const n of project.parts[part].filter(n=>Math.floor(n.start_tick/ticksPerBar())===bar)){html+=`<button class="note ${selected===n.id?'active':''}" data-note="${n.id}" style="left:${15+(n.start_tick%ticksPerBar())/ticksPerBar()*80}%;top:${(n.string-1)*15}px" aria-label="Measure ${bar+1}, string ${n.string}, fret ${n.fret}, ${pitchName(n.pitch)}">${n.fret}${n.technique?`<small>${n.technique}</small>`:''}</button>`}html+='</div>'}html+='</div>'}$('#tablature').innerHTML=html;$('#tablature').style.zoom=zoom;$$('[data-note]').forEach(el=>el.onclick=()=>{selected=el.dataset.note;renderScore();inspect()});highlight()}
function inspect(){const n=project.parts[part].find(n=>n.id===selected);$('#noteEmpty').hidden=!!n;$('#noteForm').hidden=!n;if(!n)return;$('#notePitch').textContent=pitchName(n.pitch);$('#notePosition').textContent=`Measure ${Math.floor(n.start_tick/ticksPerBar())+1} · ${(n.start_tick/project.bpm/8).toFixed(3)} s`;$('#noteString').value=n.string;$('#noteFret').value=n.fret;$('#noteLength').value=n.duration_ticks;$('#noteStart').value=n.start_tick;$('#noteTechnique').value=n.technique}
$('#noteForm').onsubmit=e=>{e.preventDefault();pause();const n=project.parts[part].find(n=>n.id===selected);const string=+$('#noteString').value,fret=+$('#noteFret').value,length=+$('#noteLength').value,start=+$('#noteStart').value;if(!Number.isInteger(fret)||fret<0||fret>24||!Number.isInteger(length)||length<1||!Number.isInteger(start)||start<0)return toast('Choose a fret from 0 to 24.');const conflict=project.parts[part].some(o=>o.id!==n.id&&o.string===string&&o.start_tick<start+length&&o.start_tick+o.duration_ticks>start);if(conflict)return toast('Another note overlaps on this string. Choose a different string or length.');const stored=JSON.parse(localStorage.getItem(KEY)||'null')?.projects.find(p=>p.id===project.id);if(stored&&stored.revision!==project.revision){return toast('This project changed in another tab. Reopen it from My projects.')}Object.assign(n,{string,fret,pitch:OPEN[string-1]+fret,duration_ticks:length,start_tick:start,technique:$('#noteTechnique').value,techniqueSource:'user-edited'});project.duration=Math.max(project.duration,(start+length)/project.bpm/8);project.revision++;if(!data.projects.some(p=>p.id===project.id))data.projects.push(project);if(persist()){render();toast('Revision '+project.revision+' saved in this browser.')}};

$('#zoomIn').onclick=()=>{zoom=Math.min(1.5,zoom+.1);$('#zoomLabel').textContent=Math.round(zoom*100)+'%';renderScore()};$('#zoomOut').onclick=()=>{zoom=Math.max(.8,zoom-.1);$('#zoomLabel').textContent=Math.round(zoom*100)+'%';renderScore()};
function highlight(){const tick=position*project.bpm/60*480;const bar=Math.floor(tick/ticksPerBar());$$('.measure').forEach(e=>e.classList.toggle('playing',+e.dataset.bar===bar));$$('[data-note]').forEach(e=>{const n=project.parts[part].find(n=>n.id===e.dataset.note);e.classList.toggle('current',playing&&tick>=n.start_tick&&tick<n.start_tick+n.duration_ticks)});if(bar!==lastBar&&playing&&$('#autoScroll').checked){const el=$(`[data-bar="${bar}"]`);if(el){const paper=$('#scorePaper'),bottom=el.getBoundingClientRect().bottom,top=el.getBoundingClientRect().top;if(bottom>paper.getBoundingClientRect().bottom-25||top<paper.getBoundingClientRect().top)paper.scrollTop+=top-paper.getBoundingClientRect().top-100}}lastBar=bar}
function tone(n){if(!ctx)return;const speed=+$('#speed').value,len=n.duration_ticks/480*60/project.bpm/speed;const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='triangle';osc.frequency.value=440*Math.pow(2,(n.pitch-69)/12);if(n.technique==='b')osc.frequency.exponentialRampToValueAtTime(osc.frequency.value*Math.pow(2,2/12),ctx.currentTime+len*.7);gain.gain.setValueAtTime(0,ctx.currentTime);gain.gain.linearRampToValueAtTime(.12,ctx.currentTime+.008);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+Math.max(.03,len*.9));osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+len)}
function updateTimeline(){const d=source==='original'&&Number.isFinite(media.duration)?media.duration:duration();$('#seek').max=d;$('#seek').value=position;$('#currentTime').textContent=time(position);$('#totalTime').textContent=time(d);highlight()}
async function play(){if(playing)return pause();if(source==='original'&&!audioFiles.has(project.id))return toast('Original audio is available after uploading a file in this session.');if(source==='synth'){ctx=ctx||new AudioContext();await ctx.resume()}const d=source==='original'?media.duration:duration();if(position>=d)position=0;if(source==='original'){media.currentTime=position;media.playbackRate=+$('#speed').value;try{await media.play()}catch{return toast('Audio could not be played. Please upload it again.')}}playing=true;$('#playBtn').textContent='Ⅱ';$('#playBtn').setAttribute('aria-label','Pause');last=performance.now();lastTick=position*project.bpm/60*480-1;timer=setInterval(()=>{const now=performance.now();position=source==='original'?media.currentTime:position+(now-last)/1000*(+$('#speed').value);last=now;const tick=position*project.bpm/60*480;if(source==='synth'){project.parts[part].filter(n=>n.start_tick>lastTick&&n.start_tick<=tick).forEach(tone);lastTick=tick}updateTimeline();if(position>=d){pause();position=d;updateTimeline()}},20)}
function pause(){playing=false;clearInterval(timer);media.pause();if(ctx){ctx.close();ctx=null}$('#playBtn').textContent='▶';$('#playBtn').setAttribute('aria-label','Play')}
$('#playBtn').onclick=play;$('#restart').onclick=()=>{pause();position=0;updateTimeline()};$('#seek').oninput=e=>{pause();position=+e.target.value;if(media.src)media.currentTime=position;lastTick=position*project.bpm/60*480-1;updateTimeline()};$('#speed').onchange=()=>{const was=playing;pause();media.playbackRate=+$('#speed').value;if(was)play()};
$$('[data-source]').forEach(e=>e.onclick=()=>{pause();source=e.dataset.source;position=0;$$('[data-source]').forEach(b=>b.classList.toggle('selected',b===e));updateTimeline()});
function modal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').showModal()}
$('#closeModal').onclick=()=>{if(conversion)return toast('Cancel the active transcription first.');$('#modal').close()};$('#modal').addEventListener('cancel',e=>{if(conversion)e.preventDefault()});
function showUpload(){pause();modal('Transcribe your recording.',`<p>Muscriptor analyses audio on your local model server and returns instrument-labelled notes and MIDI.</p><form id="uploadForm"><div class="dropzone" id="dropzone"><strong>Drop your song here</strong><p>MP3, WAV or M4A · 100 MB maximum · 5 minutes maximum</p><input id="audioFile" type="file" accept=".mp3,.wav,.m4a" required aria-label="Choose audio file"></div><label>Song title<input id="uploadTitle" placeholder="Give your song a name" maxlength="100" required></label><label>Recording type<select id="recording"><option value="solo">Solo guitar / isolated stem (recommended)</option><option value="mix">Full mix (instrument-labelled transcription)</option></select></label><p id="mixNotice" hidden class="error">Muscriptor identifies instrument groups. Lead/rhythm separation and audio STEM extraction are not available.</p><label>Time signature<select id="uploadMeter"><option value="4">4/4</option><option value="2">2/4</option><option value="3">3/4</option><option value="6">6/4</option></select></label><p>Muscriptor detects instrument-labelled notes. Guitar notes are mapped to standard tuning; audio STEM separation is not included.</p><p>Standard tuning · No capo · Original note timing retained</p><p id="uploadError" class="error" role="alert"></p><button class="primary full">Transcribe with AI →</button></form>`);$('#recording').onchange=e=>$('#mixNotice').hidden=e.target.value!=='mix';const fileInput=$('#audioFile');fileInput.onchange=()=>{if(fileInput.files[0])$('#uploadTitle').value=fileInput.files[0].name.replace(/\.[^.]+$/,'')};const drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.style.background='#e9f2e8'};drop.ondragleave=()=>drop.style.background='';drop.ondrop=e=>{e.preventDefault();drop.style.background='';if(e.dataTransfer.files.length){fileInput.files=e.dataTransfer.files;fileInput.onchange()}};$('#uploadForm').onsubmit=async e=>{e.preventDefault();const f=fileInput.files[0],err=$('#uploadError'),button=e.target.querySelector('button');if(!f)return;if(!/\.(mp3|wav|m4a)$/i.test(f.name)){err.textContent='Choose an MP3, WAV or M4A file.';return}if(f.size>100*1024*1024){err.textContent='This file exceeds 100 MB.';return}button.disabled=true;button.textContent='Decoding & resampling audio…';const metadata={id:crypto.randomUUID(),title:$('#uploadTitle').value.trim()||f.name,bpm:120,recording:$('#recording').value,meter:+$('#uploadMeter').value},options={};try{const ac=new AudioContext();let decoded;try{decoded=await ac.decodeAudioData(await f.arrayBuffer())}finally{await ac.close()}if(decoded.duration>300)throw Error('This recording exceeds 5 minutes. Audio will not be trimmed.');if(decoded.duration<=0)throw Error('This recording contains no playable audio.');metadata.duration=decoded.duration;const offline=new OfflineAudioContext(1,Math.ceil(decoded.duration*22050),22050),src=offline.createBufferSource();src.buffer=decoded;src.connect(offline.destination);src.start();const mono=(await offline.startRendering()).getChannelData(0);await startConversion(f,mono,metadata,options)}catch(error){if(!$('#uploadError'))return toast(error.message);err.textContent=error.message||'This file could not be decoded.';button.disabled=false;button.textContent='Transcribe with AI →'}}}
$('#newProject').onclick=showUpload;$('#uploadTop').onclick=showUpload;
async function startConversion(file,samples,metadata){
 if(conversion)throw Error('A transcription is already running.');
 const controller=new AbortController();conversion={worker:{terminate:()=>controller.abort()}};
 $('#modalTitle').textContent='Muscriptor transcription';
 $('#modalBody').innerHTML='<p id="jobStage">Connecting to local Muscriptor…</p><p>Audio is processed by the local Muscriptor server. Keep this tab open.</p><button id="cancelConversion" class="button full">Cancel transcription</button>';
 $('#cancelConversion').onclick=()=>controller.abort();
 try{
  const form=new FormData();
  const wav=new ArrayBuffer(44+samples.length*2),v=new DataView(wav);
  const str=(o,s)=>[...s].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));
  str(0,'RIFF');v.setUint32(4,36+samples.length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,22050,true);v.setUint32(28,44100,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,samples.length*2,true);samples.forEach((s,i)=>v.setInt16(44+i*2,Math.round(Math.max(-1,Math.min(1,s))*32767),true));
  form.append('file',new Blob([wav],{type:'audio/wav'}),'recording.wav');
  metadata.instrumentMode=TranscriptionInput.configure(form,metadata.recording);
  const response=await fetch('/api/muscriptor/transcribe',{method:'POST',body:form,signal:controller.signal});
  if(!response.ok)throw Error(await response.text());
  const reader=response.body.getReader(),decoder=new TextDecoder(),starts=new Map(),events=[];let buffer='',complete=null;
  const consume=block=>{for(const line of block.split('\n')){if(!line.startsWith('data:'))continue;const e=JSON.parse(line.slice(5));if(e.type==='error')throw Error(e.message||e.error||'Muscriptor failed');if(e.type==='start')starts.set(e.index,e);if(e.type==='end'){const n=starts.get(e.start_event_index);if(n)events.push({...n,end_time:e.end_time})}if(e.type==='progress')$('#jobStage').textContent='Muscriptor: '+e.completed+' / '+e.total+' chunks';if(e.type==='transcription_complete')complete=e;}};
  while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true}).replace(/\r/g,'');let split;while((split=buffer.indexOf('\n\n'))>=0){consume(buffer.slice(0,split));buffer=buffer.slice(split+2)}}
  if(buffer.trim())consume(buffer);if(!complete)throw Error('Muscriptor disconnected before completion.');
  project=muscriptorScore(events,metadata,complete);data.projects.unshift(project);audioFiles.set(project.id,URL.createObjectURL(file));media.src=audioFiles.get(project.id);persist();saveAudio(project.id,file).catch(()=>toast('Original audio could not be saved.'));position=0;selected=null;part='guitar';$('#modal').close();showStudio();render();toast('Muscriptor transcription complete.');
 }catch(error){if(error.name==='AbortError'){$('#modal').close();toast('Transcription cancelled.')}else{$('#modalBody').innerHTML='<p class="error">'+escapeHtml(error.message)+'</p><p>Muscriptor must be running locally with authorized model weights. No alternative model is used.</p>';}}
 finally{conversion=null}
}
function muscriptorScore(events,m,complete){
 const delay=complete.beat_grid?.onset_delay||0,notes=[],unassigned=[],busy=Array(6).fill(0);
 for(const n of events.filter(n=>/guitar|distortion|overdriven/i.test(n.instrument)).sort((a,b)=>a.start_time-b.start_time)){
  const start=Math.max(0,n.start_time-delay),end=Math.min(m.duration,n.end_time-delay);if(end<=start)continue;
  const tick=Math.round(start*m.bpm*8),length=Math.max(1,Math.round((end-start)*m.bpm*8));
  const candidates=OPEN.map((open,i)=>({string:i+1,fret:n.pitch-open,i})).filter(c=>c.fret>=0&&c.fret<=24&&busy[c.i]<=tick).sort((a,b)=>a.fret-b.fret);
  if(!candidates.length){unassigned.push(n);continue}const c=candidates[0];busy[c.i]=tick+length;notes.push({id:crypto.randomUUID(),pitch:n.pitch,start_tick:tick,duration_ticks:length,string:c.string,fret:c.fret,voice:0,technique:'',start_seconds:start,duration_seconds:end-start});
 }
 if(!notes.length)throw Error('Muscriptor returned no playable guitar notes.');
 const optimized=GuitarFingering.optimize(notes,{bpm:m.bpm,ppq:480});notes.splice(0,notes.length,...optimized);
 return {...m,created:Date.now(),revision:0,engine:'Muscriptor 0.4.0',parts:{guitar:notes},originalParts:{guitar:clone(notes)},warnings:['Muscriptor instrument labels are not lead/rhythm separation. Fingering is suggested. Bar lines use a fixed 120 BPM display grid, not detected song tempo.'],rawEvents:events,unassignedNotes:unassigned,originalMidiBase64:complete.data,beatGrid:complete.beat_grid};
}
