$('#studioNav').onclick=showStudio;$('#projectsNav').onclick=()=>{pause();try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored)data=stored}catch{}data.projects=data.projects.filter(p=>Date.now()-p.created<30*86400000);persist();$('#studio').hidden=true;$('#projects').hidden=false;$('#studioNav').classList.remove('active');$('#projectsNav').classList.add('active');$('#crumb').textContent='My projects';renderProjects()};
function renderProjects(){quota();$('#projectList').innerHTML=data.projects.length?data.projects.map(p=>`<div class="project-row"><span class="avatar">♫</span><div><h3>${escapeHtml(p.title)}</h3><p>AI transcription · Revision ${p.revision} · Expires ${new Date(p.created+30*86400000).toLocaleDateString(window.appLocale||'en-US')}</p></div><button class="button" data-open="${p.id}">Open studio →</button><button class="icon-btn" data-delete="${p.id}" aria-label="Delete ${escapeHtml(p.title)}">×</button></div>`).join(''):'<p>No projects yet. Upload a recording to transcribe. Old prototype samples are not AI results and are not listed here.</p>';$$('[data-open]').forEach(b=>b.onclick=()=>{project=data.projects.find(p=>p.id===b.dataset.open);part='guitar';selected=null;position=0;source='synth';$$('[data-source]').forEach(e=>e.classList.toggle('selected',e.dataset.source===source));if(audioFiles.has(project.id))media.src=audioFiles.get(project.id);else {media.removeAttribute('src');restoreAudio(project.id)}showStudio();render()});$$('[data-delete]').forEach(b=>b.onclick=()=>{const p=data.projects.find(p=>p.id===b.dataset.delete);modal('Delete this project?',`<p>Delete “${escapeHtml(p.title)}” and its saved edits from this browser? This cannot be undone.</p><button class="primary full" id="confirmDelete">Delete project</button>`);$('#confirmDelete').onclick=()=>{data.projects=data.projects.filter(o=>o.id!==p.id);audioRecord(p.id,'delete');if(audioFiles.has(p.id)){URL.revokeObjectURL(audioFiles.get(p.id));audioFiles.delete(p.id)}if(project.id===p.id){project=data.projects[0]||emptyProject();selected=null;position=0;render()}persist();$('#modal').close();renderProjects();toast('Project deleted.')}})}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function vlq(n){let a=[n&127];while(n>>=7)a.unshift((n&127)|128);return a}
function midi(){const events=[];project.parts[part].forEach(n=>{events.push({tick:n.start_tick,bytes:[0x90,n.pitch,90]});events.push({tick:n.start_tick+n.duration_ticks,bytes:[0x80,n.pitch,0]})});events.sort((a,b)=>a.tick-b.tick||a.bytes[0]-b.bytes[0]);const tempo=Math.round(60000000/project.bpm);let track=[0,255,81,3,(tempo>>16)&255,(tempo>>8)&255,tempo&255,0,255,88,4,(project.meter||4),2,24,8,0,192,26],prev=0;for(const e of events){track.push(...vlq(e.tick-prev),...e.bytes);prev=e.tick}track.push(0,255,47,0);const len=track.length;return new Uint8Array([77,84,104,100,0,0,0,6,0,0,0,1,1,224,77,84,114,107,(len>>>24)&255,(len>>>16)&255,(len>>>8)&255,len&255,...track])}
$('#exportBtn').onclick=()=>{pause();modal('Take your practice with you.',`<p>${escapeHtml(project.title)} · Guitar · Revision ${project.revision}</p><button class="export-option" id="exportPdf"><span>PDF sheet music<small>Print the current TAB or save as PDF</small></span>↗</button><button class="export-option" id="exportMidi"><span>MIDI file<small>Edited pitches and timing · techniques not encoded</small></span>↓</button><button class="export-option" id="exportJson"><span>Editable score JSON<small>AI events, unassigned notes, original and edited score</small></span>↓</button><button class="export-option" disabled><span>TuxGuitar (.tg)<small>Unavailable · exporter integration not yet validated</small></span>—</button>`);$('#exportPdf').onclick=()=>{$('#modal').close();window.print()};$('#exportMidi').onclick=()=>{download(new Blob([midi()],{type:'audio/midi'}),`${project.title}-${part}-r${project.revision}.mid`);toast('MIDI downloaded.')};$('#exportJson').onclick=()=>download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),`${project.title}-score.json`)};
$('#feedbackBtn').onclick=()=>{let rating=0;modal('Help us find the right notes.',`<p>How did this transcription feel? Feedback stays in this browser in this prototype.</p><div class="feedback-options">${[1,2,3,4,5].map(n=>`<button data-rating="${n}" aria-label="${n} out of 5">${n} ☆</button>`).join('')}</div><label>What needs a closer listen?</label>${['Notes','Rhythm','Techniques','Part separation'].map(t=>`<label><input type="checkbox" value="${t}" class="feedbackCheck"> ${t}</label>`).join('')}<label>Optional comment<textarea id="feedbackText" placeholder="Tell us what you heard…" maxlength="2000"></textarea></label><button class="primary full" id="saveFeedback">Save feedback locally</button>`);$$('[data-rating]').forEach(b=>b.onclick=()=>{rating=+b.dataset.rating;$$('[data-rating]').forEach(e=>e.classList.toggle('selected',+e.dataset.rating<=rating))});$('#saveFeedback').onclick=()=>{if(!rating)return toast('Choose a rating from 1 to 5.');data.feedback=data.feedback||[];data.feedback.push({project:project.id,revision:project.revision,rating,categories:$$('.feedbackCheck:checked').map(e=>e.value),comment:$('#feedbackText').value,date:Date.now()});persist();$('#modal').close();toast('Thanks — your feedback is saved locally.')}};
$('#about').onclick=()=>modal('Muscriptor', '<p>Local Muscriptor server → instrument-labelled notes and MIDI → guitar fingering → TAB. No audio stem separation or lead/rhythm separation is implemented. No alternative transcription model is used.</p>');
function audioRecord(id,mode,file){return new Promise((resolve,reject)=>{const req=indexedDB.open('mtt-audio',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result,tx=db.transaction('files',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('files'),op=mode==='get'?store.get(id):mode==='delete'?store.delete(id):store.put(file,id);let value;op.onsuccess=()=>value=op.result;tx.oncomplete=()=>{db.close();resolve(value)};tx.onerror=()=>{db.close();reject(tx.error)}}})}
function saveAudio(id,file){return audioRecord(id,'put',file)}
async function restoreAudio(id){try{const file=await audioRecord(id,'get');if(file){if(!audioFiles.has(id))audioFiles.set(id,URL.createObjectURL(file));if(project.id===id)media.src=audioFiles.get(id)}}catch{}}
window.addEventListener('beforeunload',()=>{if(conversion)conversion.worker.terminate()});
persist();render();if(project.id)restoreAudio(project.id);

$('#reviewBtn').onclick=()=>{pause();showExcluded()};
function showExcluded(){
 modal('Review excluded candidates', '<p>These are possible errors, not confirmed errors. Restore any genuine played note. Your original model events stay in the JSON export.</p><div class="excluded-list">'+(project.suppressedNotes||[]).map(n=>'<div class="excluded-row"><span>'+time(n.event.startTimeSeconds)+' · '+pitchName(n.event.pitchMidi)+'<small>'+(n.reason==='possible_harmonic'?'Possible harmonic':'Weak short attack')+'</small></span><button class="button" data-restore="'+n.id+'" '+(n.restored?'disabled':'')+'>'+(n.restored?'Restored':'Restore')+'</button></div>').join('')+'</div>');
 $$('[data-restore]').forEach(btn=>btn.onclick=()=>{
  const item=project.suppressedNotes.find(n=>n.id===btn.dataset.restore),e=item.event;
  const stored=JSON.parse(localStorage.getItem(KEY)||'null')?.projects.find(p=>p.id===project.id);
  if(stored&&stored.revision!==project.revision)return toast('This project changed in another tab. Reopen it first.');
  const start=Math.round(e.startTimeSeconds*project.bpm*8),length=Math.max(1,Math.round(e.durationSeconds*project.bpm*8));
  const candidates=OPEN.map((p,i)=>({string:i+1,fret:e.pitchMidi-p})).filter(c=>c.fret>=0&&c.fret<=24&&!project.parts.guitar.some(n=>n.string===c.string&&n.start_tick<start+length&&n.start_tick+n.duration_ticks>start)).sort((a,b)=>a.fret-b.fret);
  if(!candidates.length)return toast('No free playable string at this time. Edit overlapping notes first; the candidate remains in JSON.');
  project.parts.guitar.push({id:crypto.randomUUID(),pitch:e.pitchMidi,start_tick:start,duration_ticks:length,voice:0,...candidates[0],technique:'',start_seconds:e.startTimeSeconds,duration_seconds:e.durationSeconds,amplitude:e.amplitude,pitch_bends:e.pitchBends||[]});
  item.restored=true;project.revision++;if(persist()){render();$('#modal').close();showExcluded();toast('Note restored to TAB, playback and MIDI.')}else toast('Restored in memory only. Export JSON to keep it.');
 });
}
